    if (m.author && (m.author.kind === 'cat' ? ownCat(m.author) : m.author.user_id === meId())) row.dataset.mine = 'true';
    const body = el('div', 'neko-lobby-message__body'), meta = el('div', 'neko-lobby-message__meta');
